import type { JobApplication } from './job-application-model';
import type { NetworkingContact } from './networking-contact-model';

export interface ContactApplication {
  /**
   * @displayName Contact Application
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Contact Application Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  contactApplicationName: string;
  /**
   * @displayName Job Application
   * @validationRule Required for create/update operations
   */
  jobApplication: Pick<JobApplication, 'id' | 'role'>;
  /**
   * @displayName Contact
   * @validationRule Required for create/update operations
   */
  networkingContact: Pick<NetworkingContact, 'id' | 'contactName'>;
}

export const _ContactApplication = 'ContactApplication' as const;